use moloch_live_runtime::{probabilistic_portfolio::*,semantic_states::{self as sem,Compiled,Review,Contract,Source,State,StateKind,PayoutRule,OriginalSource},dispatch::DispatchLog,value_surface::BoundSurface,inventory};
use serde_json::{json,Value};
use sha2::{Sha256,Digest};
use std::collections::{BTreeMap,BTreeSet};
#[path="support/value_surface_fixture.rs"]mod support;
use support::{F,NOW,iso};
const U:i128=1_000_000;
fn hash<T:serde::Serialize>(v:&T)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn raw(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn input(f:&F)->PolicyInput{PolicyInput{version:1,run_id:"surface-fixture".into(),bank_manifest_sha256:f.bank.manifest_hash().as_str().unwrap().into(),valid_until_ms:NOW+100000,quantities:vec![5],maximum_enumerations:10000,maximum_gross_buy_cost:10*U,minimum_expected_gain:1,maximum_incremental_cvar_loss:20*U,maximum_terminal_cvar_loss:20*U,tail_ppm:100000,capital_rate_ppm_per_day:0,fee_per_share:0,maximum_book_age_ms:10000,maximum_plan_age_ms:5000,factors:BTreeMap::new()}}
fn policy(p:&PolicyInput)->Policy{let b=serde_json::to_vec(p).unwrap();let sha=raw(&b);Policy::load(&b,&sha,&BTreeSet::from([sha.clone()])).unwrap()}
fn semantics(f:&F,surface:&BoundSurface,exception:bool)->Compiled{
 let bytes=f.receipts.iter().map(|r|serde_json::to_vec(r).unwrap()).collect::<Vec<_>>();let hashes=bytes.iter().map(|b|raw(b)).collect::<Vec<_>>();
 let contracts=f.reviews.iter().enumerate().map(|(i,r)|Contract{market_id:r.market_id.clone(),exchange_id:r.exchange_id.clone(),contract_id:r.contract_id.clone(),official_root_sha256:r.official_contract_root_sha256.clone(),original_node_sha256:hashes[i].clone(),predicate:"Synthetic explicit reviewed party predicate; no title inference".into(),unresolved_exceptions:vec!["Synthetic review only; not actual contract resolver proof".into()]}).collect();
 let mut states=surface.scenarios().iter().map(|s|State{id:s.id.clone(),kind:StateKind::PartyWinner,outcomes:s.payout_micros.iter().enumerate().map(|(i,p)|if (*p==U)==(surface.contracts()[i].side==moloch_replay::Side::Yes){PayoutRule::ResolvedYes}else{PayoutRule::ResolvedNo}).collect(),source_sha256:hashes.clone(),assumption_label:"Explicit reviewed ordinary mapping".into()}).collect::<Vec<_>>();
 let mut weights=BTreeMap::new();if exception{states.push(State{id:"independent-cancel".into(),kind:StateKind::Cancelled,outcomes:vec![PayoutRule::RefundPrincipal;5],source_sha256:hashes.clone(),assumption_label:"Explicit synthetic 10% common cancellation stress; not learned by Atlas".into()});weights.insert("independent-cancel".into(),100000);}
 let r=Review{version:1,review_id:"portfolio-review".into(),run_id:"surface-fixture".into(),bank_manifest_sha256:f.bank.manifest_hash().as_str().unwrap().into(),tournament_id:f.scope.tournament_id.clone(),tournament_slug:f.scope.tournament_slug.clone(),scenario_source_sha256:surface.source_sha256().into(),reviewed_at_ms:NOW,valid_until_ms:NOW+100000,contracts,states,sources:hashes.iter().map(|h|Source{sha256:h.clone(),observed_at_ms:NOW,maximum_age_ms:120000}).collect(),excluded_states:vec!["Other legal/finality possibilities not guaranteed covered".into()],probabilities_are_reviewed_assumptions:true,exception_weights_ppm:weights};
 let review=serde_json::to_vec(&r).unwrap();let sha=raw(&review);sem::compile(&review,&sha,&BTreeSet::from([sha.clone()]),&bytes.iter().zip(&hashes).map(|(b,h)|OriginalSource{sha256:h,bytes:b}).collect::<Vec<_>>(),NOW).unwrap()
}
fn log(f:&F)->DispatchLog{DispatchLog::open(&f.root.join("optimizer-dispatch.jsonl")).unwrap()}
fn run(f:&F,p:&PolicyInput,stress:bool)->Option<Plan>{let s=f.bound(NOW).unwrap();let c=semantics(f,&s,stress);optimize(&f.bank,&log(f),&f.scope,&s,&c,&policy(p),NOW).unwrap()}
fn held(f:&mut F,index:usize,q:u64,price:f64){let ex=(101+index).to_string();let m=(201+index).to_string();let r=baal_transport_service::Receipt{endpoint:"/tournaments/cup/portfolio/positions".into(),request_started_at:iso(NOW),received_at:iso(NOW),status:200,data:json!({"positions":[{"exchangeId":ex,"marketId":m,"quantity":q,"costBasis":q as f64*price,"lots":[{"lotId":"9101","quantity":q,"side":"YES","entryPrice":price,"openedAt":iso(NOW-1000)}]}]})};let e=inventory::adoption(&r,f.bank.engine(),"cup","cup",&f.scope.exchanges,&iso(NOW)).unwrap();f.bank.accept("optimizer-adoption",1,&e).unwrap();for(i,q)in f.bank.engine().order_records().into_iter().filter(|q|q["retired"]==false).enumerate(){f.bank.accept("optimizer-retire",i as u64+1,&json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"receivedAt":iso(NOW)})).unwrap();}}
#[test]fn fractional_cvar_boundary_and_positive_scenarios_are_exact(){assert_eq!(cvar_loss(&[(-10,50000),(20,950000)],100000).unwrap(),5);assert_eq!(cvar_loss(&[(-1,1),(2,999999)],3).unwrap(),1);assert_eq!(cvar_loss(&[(10,1000000)],1).unwrap(),0);assert!(cvar_loss(&[(0,999999)],1).is_err());}
#[test]fn exceptional_mass_scaling_is_exact_stable_and_no_probability_invention(){let w=scaled_ordinary_weights(&[("b".into(),333333),("a".into(),666667)],999999).unwrap();assert_eq!(w.values().sum::<u32>(),999999);assert_eq!(w["a"],666666);assert_eq!(w["b"],333333);assert!(scaled_ordinary_weights(&[("a".into(),500000)],900000).is_err());}
#[test]fn real_session_joint_plan_uses_current_full_depth_and_no_false_guarantee(){let f=F::new();let p=input(&f);let before=f.bank.engine().report().unwrap();let plan=run(&f,&p,false).unwrap();assert_eq!(plan.legs().len(),2);assert!(plan.legs().iter().all(|l|l.limit_price==360000&&l.quantity==5));assert_eq!(plan.metrics().gross_buy_funding,3_600_000);assert_eq!(plan.metrics().expected_increment_numerator,1_400_000*U);assert!(plan.metrics().minimum_modeled_increment<0||plan.metrics().minimum_modeled_increment==1_400_000);assert_eq!(plan.proof()["guaranteedArbitrage"],false);assert_eq!(plan.proof()["executionProbability"],Value::Null);assert_eq!(f.bank.engine().report().unwrap(),before);let basket=plan.basket("fixture:plan","cup").unwrap();assert_eq!(basket.legs.len(),2);assert_eq!(basket.maximum_gross_buy_cost,"3.600000");assert!(basket.relationship_constraint.is_none());}
#[test]fn shared_gross_cash_does_not_spend_projected_sale_or_cancellation_credit(){let mut f=F::new();held(&mut f,0,5,0.2);let mut p=input(&f);p.maximum_gross_buy_cost=1_000_000;let plan=run(&f,&p,false);if let Some(plan)=plan{assert!(plan.legs().iter().all(|l|l.action=="sell"));assert_eq!(plan.metrics().gross_buy_funding,0);} }
#[test]fn capital_opportunity_cost_can_remove_all_positive_choices(){let f=F::new();let mut p=input(&f);p.capital_rate_ppm_per_day=u32::MAX;assert!(run(&f,&p,false).is_none());}
#[test]fn original_fifo_basis_not_weighted_price_controls_refund_and_terminal_wealth(){let mut f=F::new();held(&mut f,0,5,0.8);let plan=run(&f,&input(&f),true).unwrap();assert_eq!(plan.metrics().modeled_sleeve_basis,4*U);assert_eq!(plan.proof()["exceptionWeightsPpm"]["independent-cancel"],100000);assert!(plan.metrics().expected_increment_numerator>0);}
#[test]fn factor_neutral_joint_choice_survives_when_individual_leg_is_forbidden(){let f=F::new();let mut p=input(&f);p.factors.insert("national".into(),FactorLimit{maximum_absolute_shares_micros:0,loading_ppm:vec![U,U,U,U,-U]});let plan=run(&f,&p,false).unwrap();assert_eq!(plan.legs().len(),2);assert_eq!(plan.legs()[0].exchange_id,"104");assert_eq!(plan.legs()[1].exchange_id,"105");}
#[test]fn inadequate_full_depth_and_notional_caps_remove_large_lattice_points(){let mut f=F::new();f.book(3,NOW,"0.350000","0.360000",2);f.book(4,NOW,"0.350000","0.360000",2);assert!(run(&f,&input(&f),false).is_none());let f=F::new();let mut p=input(&f);p.maximum_gross_buy_cost=1;assert!(run(&f,&p,false).is_none());}
#[test]fn enumeration_bound_rejects_unbounded_optimizer_work(){let f=F::new();let mut p=input(&f);p.maximum_enumerations=2;let s=f.bound(NOW).unwrap();let c=semantics(&f,&s,false);assert!(optimize(&f.bank,&log(&f),&f.scope,&s,&c,&policy(&p),NOW).is_err());}
#[test]fn unchanged_head_validates_then_book_mutation_or_expiry_invalidates_opaque_plan(){let mut f=F::new();let cfg=policy(&input(&f));let s=f.bound(NOW).unwrap();let c=semantics(&f,&s,false);let l=log(&f);let plan=optimize(&f.bank,&l,&f.scope,&s,&c,&cfg,NOW).unwrap().unwrap();plan.validate_current(&f.bank,&l,&f.scope,&cfg,NOW).unwrap();assert!(plan.validate_current(&f.bank,&l,&f.scope,&cfg,plan.expires_at_ms()).is_err());f.book(3,NOW+1,"0.350000","0.365000",20);assert!(plan.validate_current(&f.bank,&l,&f.scope,&cfg,NOW+1).is_err());}
#[test]fn wrong_policy_approval_or_bank_and_unreviewed_fee_deny(){let f=F::new();let mut p=input(&f);let bytes=serde_json::to_vec(&p).unwrap();assert!(Policy::load(&bytes,&raw(&bytes),&BTreeSet::new()).is_err());p.run_id="another-run".into();let s=f.bound(NOW).unwrap();let c=semantics(&f,&s,false);assert!(optimize(&f.bank,&log(&f),&f.scope,&s,&c,&policy(&p),NOW).is_err());p=input(&f);p.fee_per_share=1;assert!(optimize(&f.bank,&log(&f),&f.scope,&s,&c,&policy(&p),NOW).is_err());}
#[test]fn no_side_uses_complement_depth_and_explicit_underlying_yes_payout_rule(){use moloch_live_runtime::{fundamental_policy::review_sha256,value_surface::mapping_sha256};let mut f=F::new();f.reviews[3].side="NO".into();let sha=review_sha256(&f.reviews[3]).unwrap();f.trusted_reviews.insert(sha.clone());f.mappings[3].review_sha256=sha;f.trusted_mappings.insert(mapping_sha256(&f.mappings[3]).unwrap());f.book(3,NOW,"0.640000","0.650000",20);let plan=run(&f,&input(&f),false).unwrap();let leg=plan.legs().iter().find(|l|l.exchange_id=="104").unwrap();assert_eq!(leg.side,sem::Side::No);assert_eq!(leg.limit_price,360000);}
#[test]fn full_wire_limit_funding_is_conservative_not_weighted_depth_cost(){let mut f=F::new();f.sequences[3]+=1;let seq=f.sequences[3];f.bank.accept("surface-books-3",seq,&json!({"type":"book","receivedAt":iso(NOW),"book":{"marketId":"204","exchangeId":"104","tournamentId":"cup","sequence":seq.to_string(),"sourceAt":iso(NOW),"requestStartedAt":iso(NOW),"receivedAt":iso(NOW),"bids":[{"price":"0.350000","quantity":20}],"asks":[{"price":"0.360000","quantity":2},{"price":"0.400000","quantity":3}]}})).unwrap();let plan=run(&f,&input(&f),false).unwrap();assert_eq!(plan.metrics().gross_buy_funding,3_800_000);assert_eq!(plan.legs().iter().find(|l|l.exchange_id=="104").unwrap().limit_price,400000);}
